    if (intArray[i]<min)
      min = intArray[i];
    else if (intArray[i]>max)
      max = intArray[i];
  }
  int mid = (min + max) / 2;
  for (int i=0; i<intArray.length; ++i)
    if (intArray[i]<mid)
      intArray[i] = min;
    else
      intArray[i] = max;
}

