public static boolean find(
                       Comparable[] array,
                       Comparable item) {
  if (array == null) return false;
  int front = 0, back = array.length;
  do {
    int mid = (front + back)/2;
    if (array[mid].compareTo(item)==0)
      return true;
    else if (array[mid].compareTo(item)<0)
      front = mid+1;
    else
      back = mid-1;
  } while (front<=back);
  return false;
}

